import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[] a = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();

        int n1 = n / 2;
        List<Integer> a1 = new ArrayList<>();
        List<Integer> a2 = new ArrayList<>();

        // Generate all subset sums for first half
        sums1(a, 0, n1, 0, m, a1);
        // Generate all subset sums for second half
        sums2(a, n1, n, 0, m, a2);

        // Remove duplicates and sort
        Set<Integer> setA1 = new HashSet<>(a1);
        a1 = new ArrayList<>(setA1);
        Collections.sort(a1);

        // For binary search
        List<Integer> resultList = new ArrayList<>();
        for (int val : a2) {
            int answer = solve(val, a1, m);
            resultList.add(answer);
        }
        System.out.println(resultList.get(resultList.size() - 1));
    }

    private static void sums1(int[] a, int index, int end, int sum, int m, List<Integer> list) {
        if (index == end) {
            list.add(sum % m);
            return;
        }
        sums1(a, index + 1, end, sum + a[index], m, list);
        sums1(a, index + 1, end, sum, m, list);
    }

    private static void sums2(int[] a, int start, int end, int sum, int m, List<Integer> list) {
        if (start == end) {
            list.add(sum % m);
            return;
        }
        sums2(a, start + 1, end, sum + a[start], m, list);
        sums2(a, start + 1, end, sum, m, list);
    }

    private static int solve(int val, List<Integer> a1, int m) {
        int idx = Collections.binarySearch(a1, m - val);
        if (idx < 0) {
            idx = -idx - 1; // insertion point
        }
        int res = 0;
        if (idx > 0) {
            res = a1.get(idx - 1) + val;
        }
        return res;
    }
}
